import React, { useState, useEffect } from 'react';
import {
  Box,
  TextField,
  Button,
  Typography,
  Autocomplete,
  MenuItem,
  Paper,
  Alert,
  CircularProgress
} from '@mui/material';
import axios from 'axios';

const merchandiseTypes = [
  'T-Shirt',
  'Hoodie',
  'Hat',
  'Water Bottle',
  'Stickers',
  'Other'
];

function RequestForm() {
  const [collegeQuery, setCollegeQuery] = useState('');
  const [colleges, setColleges] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const [formData, setFormData] = useState({
    college_name: '',
    email: '',
    merchandise_type: '',
    quantity: 1
  });

  useEffect(() => {
    const searchColleges = async () => {
      if (collegeQuery.length < 2) return;

      setLoading(true);
      try {
        const response = await axios.get(`http://localhost:5000/api/search-colleges?query=${collegeQuery}`);
        setColleges(response.data);
      } catch (err) {
        setError('Failed to search colleges. Please try again.');
      } finally {
        setLoading(false);
      }
    };

    const timeoutId = setTimeout(searchColleges, 300);
    return () => clearTimeout(timeoutId);
  }, [collegeQuery]);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setSuccess('');

    try {
      await axios.post('http://localhost:5000/api/submit-request', formData);
      setSuccess('Request submitted successfully!');
      setFormData({
        college_name: '',
        email: '',
        merchandise_type: '',
        quantity: 1
      });
    } catch (err) {
      setError(err.response?.data?.error || 'Failed to submit request. Please try again.');
    }
  };

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: value
    }));
  };

  return (
    <Paper elevation={3} sx={{ p: 4, maxWidth: 600, mx: 'auto', mt: 4 }}>
      <Typography variant="h4" component="h1" gutterBottom>
        College Merchandise Request
      </Typography>

      {error && <Alert severity="error" sx={{ mb: 2 }}>{error}</Alert>}
      {success && <Alert severity="success" sx={{ mb: 2 }}>{success}</Alert>}

      <Box component="form" onSubmit={handleSubmit} sx={{ mt: 2 }}>
        <Autocomplete
          options={colleges}
          getOptionLabel={(option) => `${option.name} (${option.city}, ${option.state})`}
          loading={loading}
          onChange={(event, newValue) => {
            setFormData(prev => ({
              ...prev,
              college_name: newValue ? newValue.name : ''
            }));
          }}
          renderInput={(params) => (
            <TextField
              {...params}
              label="College Name"
              required
              fullWidth
              value={collegeQuery}
              onChange={(e) => setCollegeQuery(e.target.value)}
              InputProps={{
                ...params.InputProps,
                endAdornment: (
                  <>
                    {loading ? <CircularProgress color="inherit" size={20} /> : null}
                    {params.InputProps.endAdornment}
                  </>
                ),
              }}
            />
          )}
          sx={{ mb: 2 }}
        />

        <TextField
          label="Email"
          type="email"
          name="email"
          value={formData.email}
          onChange={handleChange}
          required
          fullWidth
          sx={{ mb: 2 }}
        />

        <TextField
          select
          label="Merchandise Type"
          name="merchandise_type"
          value={formData.merchandise_type}
          onChange={handleChange}
          required
          fullWidth
          sx={{ mb: 2 }}
        >
          {merchandiseTypes.map((type) => (
            <MenuItem key={type} value={type}>
              {type}
            </MenuItem>
          ))}
        </TextField>

        <TextField
          label="Quantity"
          type="number"
          name="quantity"
          value={formData.quantity}
          onChange={handleChange}
          required
          fullWidth
          inputProps={{ min: 1 }}
          sx={{ mb: 3 }}
        />

        <Button
          type="submit"
          variant="contained"
          color="primary"
          size="large"
          fullWidth
        >
          Submit Request
        </Button>
      </Box>
    </Paper>
  );
}

export default RequestForm;
